// Aggregates metrics for conversations from the last 24 h
const desde = Date.now() / 1000 - 24 * 60 * 60;
const items = $input.all().map((i) => i.json);

// The date field may be called fecha / fecha_ini (epoch) depending on the account
const recientes = items.filter((c) => {
	const f = Number(c.fecha ?? c.fecha_ini ?? 0);
	return !f || f >= desde;
});

const porCanal = {};
const porUsuario = {};
for (const c of recientes) {
	const canal = String(c.id_canal ?? 'unknown');
	porCanal[canal] = (porCanal[canal] || 0) + 1;
	const usuario = String(c.id_usuario ?? 'unassigned');
	porUsuario[usuario] = (porUsuario[usuario] || 0) + 1;
}

const lineas = [
	`📊 Daily conversation report`,
	`Total (last 24 h): ${recientes.length}`,
	'',
	'By channel:',
	...Object.entries(porCanal).map(([k, v]) => `  • Channel ${k}: ${v}`),
	'',
	'By agent:',
	...Object.entries(porUsuario).map(([k, v]) => `  • User ${k}: ${v}`),
];

return [{ json: { resumen: lineas.join('\n'), total: recientes.length, porCanal, porUsuario } }];
